(function(){
  'use strict';
  const G=window.StudioGame, P=window.StudioPeople, $=id=>document.getElementById(id);
  const SAVE='loop_studio_career_v8';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const yen=n=>'¥'+Math.round(n).toLocaleString('zh-CN');
  const pct=(n,d)=>Math.max(0,Math.min(100,Math.floor(n/d*100)));
  let run=null,meta=G.emptyMeta(),view='home',tab='work',hiddenPrompt=false,setupScale='micro',toastTimer,storageOK=true;
  try{const snapshot=JSON.parse(localStorage.getItem(SAVE)||'null');if(snapshot&&G.validateMeta(snapshot.meta)&&(!snapshot.run?!snapshot.meta.activeRunId:G.validateRun(snapshot.run)&&(snapshot.run.over||snapshot.meta.activeRunId===snapshot.run.id))){meta=snapshot.meta;run=snapshot.run;}}catch{}

  const audio=window.DSHAudio.create(window);audio.init(updateAudio);
  function updateAudio(){const a=audio.getState();const muted=a.settings?.muted??a.muted;const b=$('audio-toggle');b.classList.toggle('on',!muted);b.setAttribute('aria-label',muted?'开启声音':'关闭声音');b.title=muted?'开启声音':'关闭声音';}
  function save(){G.syncCareer(meta,run);try{localStorage.setItem(SAVE,JSON.stringify({meta,run}));}catch{if(storageOK){storageOK=false;toast('浏览器未允许保存，当前进度仅在本次打开期间保留。');}}}
  function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('toast');toastTimer=setTimeout(()=>$('toast').classList.remove('toast'),3200);}
  function disabled(ok){return ok?'':' disabled';}
  function busy(){return !run||run.over||run.pendingEvent;}
  function bar(value,max,color){return `<div class="progress" style="--bar:${color||'var(--teal)'}"><span style="width:${pct(value,max)}%"></span></div>`;}
  function metricHelpButton(id){const name=id==='morale'?'士气':'技术债';return `<button type="button" class="metric-help-trigger" data-metric-help="${id}" aria-label="查看${name}说明" aria-haspopup="dialog" aria-expanded="false" aria-controls="metric-help">?</button>`;}
  function metricHelpContent(s,id){
    const morale=id==='morale',name=morale?'士气':'技术债';
    const body=morale?`<div class="metric-help-current">当前 ${Math.round(s.morale)} / 100<span>全岗位产出系数 ×${((.65+s.morale/285)*100).toFixed(1)}%</span></div>
      <p>士气影响所有岗位的每周产出，与能力、节奏等效果相乘。</p><ul><li>正常开发：每周士气 +1。</li><li>休整：当周产出 ×70%，士气 +12。</li><li>赶工：当周产出 ×135%，士气 −10。</li><li>士气低于 65，疲劳类事件会进入随机池。</li></ul><p class="metric-help-foot">士气范围 25—100，每个新项目从 90 开始。产出系数 = 0.65 + 士气 ÷ 285。</p>`:
      `<div class="metric-help-current">当前 ${s.debt.toFixed(1)} 点<span>程序产出系数 ×${(Math.max(.6,1-s.debt*.01)*100).toFixed(1)}%</span></div>
      <div class="metric-help-effects"><span>每周额外基础维护 <b>+${yen(s.debt*2)}</b></span><span>新增问题产生系数 <b>×${(1+s.debt/25).toFixed(2)}</b></span><span>完善度真实分数 <b>−${(s.debt*.18).toFixed(2)}</b></span></div>
      <p>每点技术债使程序岗位效率降低 1%，最低为 60%；影响开发进度和系统协作。每点另增加约 ¥2/周维护费，并放大开发产生的新问题。</p><ul><li>安排系统协作可持续偿债，完成度已满时仍有效。</li><li>开发、追加功能、解冻与赶工会增加技术债；赶工额外 +2/周。</li><li>测试修复问题，不直接偿还技术债。部分事件也可偿债。</li></ul><p class="metric-help-foot">每个新项目从 0 开始。新增问题还受开发量、节奏、范围冻结与测试影响；这里显示的是技术债本身的作用。</p>`;
    return `<header><h2 id="metric-help-title">${name}说明</h2><button type="button" class="metric-help-close" aria-label="关闭数值说明">×</button></header>${body}`;
  }
  function positionMetricHelp(){
    if(!metricTrigger||metricPopup.hidden)return;
    const r=metricTrigger.getBoundingClientRect(),w=metricPopup.offsetWidth,h=metricPopup.offsetHeight,pad=12;
    metricPopup.style.left=Math.max(pad,Math.min(innerWidth-w-pad,r.left+r.width/2-w/2))+'px';
    const below=r.bottom+8,above=r.top-h-8;
    metricPopup.style.top=Math.max(pad,Math.min(innerHeight-h-pad,below+h<=innerHeight-pad?below:above))+'px';
  }
  function hideMetricHelp(restoreFocus=false){
    clearTimeout(metricHideTimer);const trigger=metricTrigger;
    if(trigger)trigger.setAttribute('aria-expanded','false');
    metricTrigger=null;metricPinned=false;metricPopup.hidden=true;
    if(restoreFocus&&trigger?.isConnected){suppressMetricFocus=true;trigger.focus();suppressMetricFocus=false;}
  }
  function showMetricHelp(trigger,pinned=false){
    const id=trigger.dataset.metricHelp;if(!run||!['morale','debt'].includes(id))return;
    clearTimeout(metricHideTimer);if(metricTrigger&&metricTrigger!==trigger)metricTrigger.setAttribute('aria-expanded','false');
    metricTrigger=trigger;metricPinned=pinned;metricPopup.innerHTML=metricHelpContent(run,id);metricPopup.hidden=false;
    trigger.setAttribute('aria-expanded','true');positionMetricHelp();
  }
  function scheduleMetricHide(){clearTimeout(metricHideTimer);metricHideTimer=setTimeout(()=>{if(!metricPinned)hideMetricHelp();},160);}

  function title(eye,name,sub,right=''){return `<div class="title-row"><div><div class="eyebrow">${eye}</div><h1>${name}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</div>`;}
  function officeSVG(){
    const people=run?G.teamSize(run):2;
    const desks=[{x:156,y:170,c:'#92bca8'},{x:268,y:170,c:'#a6afe0'},{x:213,y:239,c:'#d8bb80'},{x:325,y:239,c:'#d8a991'}];
    return `<svg class="office-art" viewBox="0 0 530 350" aria-label="像素风工作室，团队在温暖灯光下制作游戏" role="img"><defs><pattern id="floor" width="38" height="38" patternUnits="userSpaceOnUse" patternTransform="matrix(1 .5 -1 .5 0 0)"><rect width="38" height="38" fill="#384a43"/><path d="M0 0h38v38" fill="none" stroke="#4a5a4f" stroke-width="1"/></pattern><linearGradient id="windowlight" x2="0" y2="1"><stop stop-color="#a1c6ae"/><stop offset="1" stop-color="#6d9c91"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="6"/></filter></defs><ellipse cx="283" cy="276" rx="185" ry="52" fill="#0f191c" opacity=".3"/><path d="M76 169 276 68 466 163 267 268Z" fill="#263932"/><path d="M76 169v48l191 98v-47Z" fill="#26352f"/><path d="M267 268v47l199-100v-52Z" fill="#1c2e2b"/><path d="M76 169 276 68 466 163 267 268Z" fill="url(#floor)"/><path d="M76 169V72L276-27v95Z" fill="#506258" transform="translate(0 24)"/><path d="M276 92V-3l190 95v95Z" fill="#344c46"/><path d="M99 105 190 60v58l-91 45Z" fill="#253d39" stroke="#72887b" stroke-width="4"/><path d="M105 106 184 67v48l-79 39Z" fill="url(#windowlight)"/><path d="M144 87v48M106 129l77-39" stroke="#3e5c50" stroke-width="4"/><path d="M107 128 113 110l8-4 2 10 9-20 9-5 3 24 11-23 12-6 8 14 8-4v18l-78 39Z" fill="#42665a" opacity=".55"/><path d="M147 142 270 203 334 171 188 115Z" fill="#e4d5a9" opacity=".065"/><path d="m219 53 33-16v29l-33 17Z" fill="#c7b794"/><path d="m225 56 20-10v16l-20 10Z" fill="#718b72"/><path d="M304 49 358 76v42l-54-27Z" fill="#233d37" stroke="#789082" stroke-width="2"/><path d="m313 65 34 17m-34-7 25 13m-25-3 30 15" stroke="#b0b68e" stroke-width="2"/><path d="m386 99 55 28v8l-55-28Z" fill="#a18a65"/><path d="m390 92 5 2v10l-5-2m9-3 5 2v8l-5-2m10-2 5 2v8l-5-2m8-3 5 2v9l-5-2" fill="#91ab96" stroke="#6d8a77" stroke-width="2"/>
    <g transform="translate(90 174)"><path d="m0 0 21-10 17 8-20 10Z" fill="#bc9a6a"/><path d="M0 0v18l18 10V8m0 20 20-10V-2" fill="#6b6044"/><path d="M18-5v-38" stroke="#547d64" stroke-width="4"/><path d="M18-16C-8-18-8-35 1-31c13 2 15 8 17 15m0-5c23-6 26-22 17-21-15 0-19 12-17 21m0-9c-14-9-13-23-7-21 10 2 11 13 7 21" fill="#739b78"/></g>
    ${desks.map((d,i)=>`<g transform="translate(${d.x} ${d.y})"><path d="m-25 0 49-25L72-1 23 24Z" fill="#b2966b" stroke="#ccb184" stroke-width="1"/><path d="M-25 0v6l48 25v-7m49-25v7L23 31v-7" fill="#73684f"/><path d="M-19 9v27m79-24v26M22 31v24" stroke="#374039" stroke-width="5"/><path d="m0-11 29-15v24L0 13Z" fill="#1b2b30" stroke="#667f76" stroke-width="2"/><path d="m3-10 23-12v18L3 8Z" fill="${run?.team?.[i]?.color||d.c}" opacity=".65"/><path d="m6-10 8-4m-8 9 15-8m-15 13 10-5" stroke="#d7e0c9" stroke-width="1" opacity=".6"/><path d="m13 13 12-6 12 6-12 6Z" fill="#566c60"/><path d="m29 8 17-8 12 6-17 8Z" fill="#aeb8a0"/><path d="m54-7 6-3v9l-6 3Z" fill="#d5c3a1"/>${i<people?`<g><path d="M8 37v15l13 7 12-7V39" fill="#26363a"/><path d="m8 34 13-7 13 7-13 7Z" fill="#526b61"/><path d="M12 23v17l10 6 9-5V23" fill="${d.c}"/><path d="m12 22 10-5 9 5v10l-9 5-10-5Z" fill="#d6ad87"/><path d="m10 19 11-6 12 6v7l-5-2-1-5-13 6-4-1Z" fill="${i%2?'#76624a':'#3c3c34'}"/><path d="m15 42-9-8m22 9 9-9" stroke="${d.c}" stroke-width="5"/></g>`:''}</g>`).join('')}
    <path d="m407 178 27-14 15 8-27 14Z" fill="#9d8c68"/><path d="M407 178v32l15 8v-32m27-14v32l-27 14v-32" fill="#526252"/><path d="m415 181 10-5 8 4-10 5Z" fill="#b7ba9e"/><path d="m396 155 6-3v18l-6 3Z" fill="#d9c198"/><path d="m384 150 16-20 17 20-17 8Z" fill="#dac28c"/><ellipse cx="401" cy="151" rx="15" ry="5" fill="#f5d795" opacity=".22" filter="url(#glow)"/></svg>`;
  }
  function home(){const live=run&&!run.over;return title('MAKE SOMETHING WORTH PLAYING','每一周，离好游戏更近一步。','一间小工作室，一个新点子，还有属于你的制作人故事。')+
    `${careerStats()}<section class="hero"><div class="hero-copy"><div class="eyebrow">下一个好点子 · 等你开工</div><h1>从一个点子，<br>到一款真正的游戏。</h1><p>安排团队，积累主角能力，应对开发中的意外。<br>时间没有终点，预算会提醒你何时该发售。</p><div class="hero-buttons"><button class="btn-primary" data-action="${live?'continue':'setup'}">${live?'继续开发「'+esc(run.name)+'」':meta.stage===1?'＋ 立项，开始第一款游戏':'＋ 立项，开始第 '+meta.stage+' 关'} <span>↗</span></button>${live?'<button class="btn-ghost" data-action="setup">新项目</button>':'<button class="btn-ghost" data-action="help">了解怎么玩 →</button>'}</div><p class="hero-note">回合开发 · 每周随机事件 · 资金继承 · 全局团队</p></div><div class="home-office">${officeSVG()}</div></section>
    <div class="section-heading"><h2>这一次，做多大的游戏？</h2><small>四档规模 · 以 100% 能力计算标准人周</small></div><div class="scale-grid">${G.SCALES.map((g,i)=>`<article class="scale-card" style="--accent:${['#d8b879','#81bea7','#76a9e7','#bc9fe4'][i]}"><div class="scale-icon">${g.icon}</div><h3>${g.name}</h3><div class="scale-meta">${g.tag}</div><p>${g.desc}</p><div class="scale-work"><small>需要</small>${G.scalePlan(g.id).personWeeks.toLocaleString("zh-CN")}<small>人周工作量 · 100% 能力</small></div><div class="scale-funds ${meta.wallet<G.scalePlan(g.id).minFunds?'insufficient':''}">立项需要 ${yen(G.scalePlan(g.id).minFunds)}<small>${meta.wallet<G.scalePlan(g.id).minFunds?'资金不足 · 还差 '+yen(G.scalePlan(g.id).minFunds-meta.wallet):'当前资金可立项'}</small></div><button data-action="setup" data-scale="${g.id}"${disabled(meta.wallet>=G.scalePlan(g.id).minFunds)}>${meta.wallet<G.scalePlan(g.id).minFunds?'资金不足':'选择这个规模 <span>↗</span>'}</button></article>`).join('')}</div>
    <div class="home-bottom"><div class="home-tip"><span>◷</span><div><h3>开发多久，由你决定</h3><p>没有固定回合上限。团队、项目范围与技术债决定每周成本。</p></div></div><div class="home-tip"><span>◇</span><div><h3>每一作，都是新的开始</h3><p>完成作品获得经验，训练主角；剩余资金与全体伙伴带到下一关。</p></div></div></div>`;
  }
  function game(){if(!run)return title('YOUR NEXT PROJECT','工作室还没有项目','从你和阿策两个人开始，安排 13 项开发工作。')+'<section class="panel empty"><h2>从第一周，开始你的作品。</h2><button data-action="setup" class="btn-primary">＋ 开始一个新项目</button></section>';
    const s=run,c=G.cost(s),p=G.preview(s),active=!busy(),g=G.SCALES.find(g=>g.id===s.scale),f=G.forecast(s);
    let html=title('PROJECT WORKBENCH',esc(s.name),`${g.name} · 需要 ${G.scalePlan(g.id).personWeeks.toLocaleString("zh-CN")} 人周工作量 · 第 ${s.stage} 关 · 五类工作 / 十三项行动 · ${s.hard?'真实模式':'理想模式'}`, `<div class="title-badges"><span class="pill gold">第 ${s.week} 周</span><span class="pill">${s.over?'项目已结束':G.canRelease(s)?'可以正式发售':'开发中'}</span></div>`);
    if(s.over)html+='<div class="notice">'+(s.result.released?'作品已经发售，真实评级已揭晓。':'项目已终止，制作经验已结算。')+' <button class="btn-small" data-action="result">查看结算</button> <button class="btn-small" data-action="setup">下一款作品 ↗</button></div>';
    if(!s.over&&s.money<c.total)html+='<div class="notice">预算不足以推进下一周。可减少买量预算、融资，或完成上架后发售。<button class="btn-small" data-action="abort">终止项目</button></div>';
    html+=`<div class="stats"><div class="stat"><div class="label">项目资金</div><div class="value gold num">${yen(s.money)}</div><div class="note">累计投入 ${yen(s.spent)}</div></div><div class="stat"><div class="label">预计可维持</div><div class="value teal num">${Math.floor(s.money/c.total)}<small>周</small></div><div class="note">没有固定回合上限</div></div><div class="stat"><div class="label">本周总支出</div><div class="value num">${yen(c.total)}</div><div class="note">工资 ${yen(c.wages)} / 维护与工具 ${yen(c.overhead+c.tools)} / 买量 ${yen(c.ads)}</div></div><div class="stat"><div class="label">工作室伙伴</div><div class="value num">${G.teamSize(s)}<small>/ 8 人</small></div><div class="note status-metrics"><span class="metric-value">士气 ${Math.round(s.morale)} ${metricHelpButton('morale')}</span><span class="metric-value">技术债 ${Math.round(s.debt)} ${metricHelpButton('debt')}</span></div></div></div>`;
    html+=strategyPanel(s,p);
    if(G.availableRecruits(s).length&&!s.over)html+=`<div class="notice recruit-notice"><span>✉ ${G.availableRecruits(s).map(m=>esc(m.name)).join('、')}发来伙伴来信。</span><button class="btn-small" data-action="tab" data-tab="team">查看人物卡 ↗</button></div>`;
    html+=`<div class="tabs" role="tablist">${[['work','开发现场'],['team','团队人物 '+G.teamSize(s)],['features','功能规划'],['logs','开发记录']].map(([id,n])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="tab" data-tab="${id}">${n}</button>`).join('')}</div>`;
    if(tab==='team')return html+P.roster(s,active);if(tab==='features')return html+features();if(tab==='logs')return html+logs();
    html+=P.strip(s,active);
    html+=`<div class="ratings-summary" aria-label="作品评级概览">${G.GROUPS.map(g=>g.id==='release'?`<a href="#group-release" class="rating-summary-item"><small>能否上架</small><strong class="${G.complete(s)?'teal':''}">${G.complete(s)?'可上架':'未就绪'}</strong><span>两项工作均须完成</span></a>`:ratingTile(s,g)).join('')}</div>`;
    html+=`<div class="development-layout"><div class="work-groups">${G.GROUPS.map(g=>workGroup(s,g,p,active)).join('')}</div><aside class="project-aside"><section class="panel"><div class="panel-head"><h2>发售准备</h2><span class="pill">${G.goals(s).filter(g=>g.ok).length} / 2</span></div><div class="panel-body"><div class="goal-list">${G.goals(s).map(g=>`<div class="goal ${g.ok?'done':''}"><span>${g.ok?'✓':'·'}</span><span>${g.name}</span><span>${g.value}</span></div>`).join('')}</div><p class="quality-note">上架两项均到 100% 才能发售。内容、程序、商业化和宣发决定品质与收益，可自行取舍投入。</p><button class="btn-teal release-btn" data-action="release"${disabled(G.canRelease(s))}>${G.canRelease(s)?'正式发售这款游戏 ↗':'完成上架后即可发售'}</button><div class="financial"><div>综合评级认知<strong>${esc(f.rating.text)}</strong></div><div>当前版本收入区间<strong>${yen(f.low)}—${yen(f.high)}</strong></div></div><p class="quality-note">区间来自当前认知，已扣发行分成；宣传越少，估算越宽。未计后续开发成本，发售时揭晓真实评级。</p></div></section>${eventPanel(s)}<section class="panel"><div class="panel-head"><h2>团队与资金</h2></div><div class="panel-body"><p class="quality-note">每人每周专注一项工作。邀请伙伴花 ¥180，暂别花 ¥100，均占本周管理行动。完成原型、切片和完整内容后结识新伙伴。</p><button class="btn-small" data-action="tab" data-tab="team">查看伙伴来信</button><div class="funding"><div><b>发行合作 · ¥2,200</b><p>${s.funding?'已合作，发售收入分成 22%':'核心平均进度 30% 可签，收入分成 22%'}</p></div><button class="btn-small" data-action="funding"${disabled(active&&!s.funding&&G.coreProgress(s)>=.3)}>${s.funding?'已签订':'了解合作'}</button></div></div></section></aside></div>`;
    return html;
  }
  function strategyPanel(s,p){const o=G.objectiveStatus(s,s.over&&s.result.released?s.result:undefined),f=G.forecast(s);return `<section class="strategy-panel"><div class="strategy-title"><div><span class="eyebrow">BUILD · LEARN · DECIDE</span><h2>${o.name} <span class="pill dim">${s.over?s.result.objectiveOK?'已达成':'未达成':o.ok?'有望达成':'开发中'}</span></h2><p>${s.objective==='acclaim'?'综合真实评级达到 A-':'发售后项目结余至少 ¥1,200'} · 达成额外 +40 EXP</p></div><div class="objective-value gold">${s.over&&s.result.released?s.objective==='acclaim'?s.result.rating:yen(s.result.profit):s.objective==='acclaim'?esc(f.rating.text):yen(f.low+s.income-s.spent)+'—'+yen(f.high+s.income-s.spent)}<small>${s.over?'实际结算':'基于当前认知，未计未来成本'}</small></div></div><div class="strategy-flow"><span>推进工作</span><b>→</b><span>积累真实品质</span><b>→</b><span>宣传验证认知</span><b>→</b><span>决定投放与发售</span></div><p class="quality-note">????? 表示完全未知；例如 B???? 是可能偏离真实值的初步判断。问号越少，误差越小。宣传改变认知，不会直接提高作品品质。</p></section>`;}
  function job(s,j,p,active){
    const assigned=s.team.filter(m=>m.job===j.id),completion=G.progress(s,j.id),cap=G.softCap(s,j.id),phase=G.workPhase(s,j.id),listing=j.group==='release',done=completion>=1,atCap=!listing&&cap<1&&completion>=cap-.0001,upstream=G.workLimit(s,j.id)<s.req[j.id]*cap-.01&&G.workLimit(s,j.id)<=s.work[j.id]+.01;
    const pp=n=>Math.abs(n)<.05?'0':(n>0?'+':'−')+Math.abs(n).toFixed(1),range=p?.ranges[j.id],low=range?range.low/s.req[j.id]*100:0,high=range?range.high/s.req[j.id]*100:0;
    const forecast=!p?'':Math.abs(high-low)<.01?'本周 '+pp(high)+' 个百分点':'本周 '+pp(low)+' ～ '+pp(high)+' 个百分点';
    const last=s.history.at(-1)?.gains?.[j.id],lastText=last?'上周实际 '+pp(last/s.req[j.id]*100)+' 个百分点':'';
    return `<div class="job work-item" data-work="${j.id}" style="--job-color:${j.color}"><div class="job-line"><div class="job-name"><strong>${j.name}</strong><small>${j.desc}</small></div></div>
      <div class="progress-label completion-label"><span>完成度 <b>${(completion*100).toFixed(1)}%</b></span><span>${listing?'目标 100% · 无软上限':'软上限 '+Math.round(cap*100)+'% · 刚性上限 100%'}</span></div>
      <div class="progress completion-bar" style="--bar:${j.color};--soft:${cap*100}%" aria-label="${j.name}完成度 ${(completion*100).toFixed(1)}%，${listing?'无软上限':'软上限 '+Math.round(cap*100)+'%'}"><span style="width:${completion*100}%"></span>${!listing&&cap<1?'<i class="soft-limit" aria-hidden="true"></i>':''}</div>
      <div class="work-units"><span>已完成 ${s.work[j.id].toFixed(1)} / ${s.req[j.id]} 点</span><span>本周基础产能 ${(p?.production[j.id]||0).toFixed(1)} 点（未计阶段与上限）</span></div>
      <div class="completion-status"><span class="${phase.id==='uncertain'?'red':''}">${phase.name}</span><span>${forecast}</span>${lastText?'<span>'+lastText+'</span>':''}</div>
      <div class="job-members">${assigned.map(m=>`<span style="color:${m.color}">${esc(m.name)} · ${G.taskSkill(m,j.id)}%${m.job!==m.lastJob?' · 磨合中':''}</span>`).join(' / ')||'未安排伙伴'}${atCap?'<span class="cap-warning"> · 已到软上限，等待事件解锁</span>':''}${upstream?'<span class="red"> · 等待上游完成度</span>':''}${j.id==='acquisition'&&s.adBudget===0?'<span> · 预算为 ¥0，暂停买量</span>':''}</div>
      ${s.hard&&phase.spill?'<p class="ops-note">本项实际推进的 20% 会从另一项非上架工作扣除；具体影响在推进后揭晓。</p>':''}
      ${s.hard&&phase.id==='uncertain'?'<p class="ops-note">即使已满或触及上限，继续安排仍可能返工。增减各 50%，幅度为基础产能的 20%—100%。</p>':''}
      ${done&&['systems','qa','acquisition'].includes(j.id)?'<p class="ops-note">'+(j.id==='systems'?'继续工作可偿还技术债。':j.id==='qa'?'继续工作可修复问题。':'继续工作仍会按本周预算追加投放。')+'</p>':''}</div>`;
  }
  function ratingTile(s,g){const v=G.ratingView(s,g.id);return `<a href="#group-${g.id}" class="rating-summary-item" style="--rating-color:${g.color}"><small>${g.rating}</small><strong class="rating-text" data-rating="${g.id}">${esc(v.text)}</strong><span>${v.exact?'真实评级已揭示':v.level?'认知范围 '+v.lowGrade+'—'+v.highGrade:'未获得玩家反馈'}</span></a>`;}
  function workGroup(s,g,p,active){const v=g.id==='release'?null:G.ratingView(s,g.id),list=G.JOBS.filter(j=>j.group===g.id);return `<section class="panel work-group" id="group-${g.id}" style="--group-color:${g.color}"><header class="work-group-head"><div><span class="eyebrow">${String(G.GROUPS.indexOf(g)+1).padStart(2,'0')} / ${g.id==='release'?'必须完成':'可自主取舍'}</span><h2>${g.icon} ${g.name}</h2></div><div class="group-verdict"><small>${g.rating}</small><strong>${v?esc(v.text):G.complete(s)?'可上架':'未就绪'}</strong>${v?`<span>${v.exact?'真实评级':v.level?'范围 '+v.lowGrade+'—'+v.highGrade:'等待反馈'}</span>`:`<span>上架总进度 ${Math.floor(G.groupProgress(s,'release')*100)}%</span>`}</div></header>${list.map(j=>job(s,j,p,active)).join('')}${g.id==='promotion'?marketing(s,active):g.id==='content'?`<div class="group-note"><span>${s.designLocked?'范围已冻结：程序 / 美术 +12%，不能扩功能。':'内容平均达 60% 可冻结范围，程序 / 美术 +12%。'}</span><button class="btn-small" data-action="freeze"${disabled(active&&!s.managed&&G.groupProgress(s,'content')>=.6&&(!s.designLocked||s.money>=180))}>${s.designLocked?'解冻 · ¥180':'冻结范围'}</button></div>`:g.id==='release'?'<p class="group-note">资料准备 100% 后才能推进审核。上架资格确定，不受评级随机值影响。</p>':''}</section>`;}
  function marketing(s,active){const a=G.adProjection(s),level=G.revealLevel(s);return `<div class="marketing-controls"><div class="reveal-progress"><strong>评级揭示 ${level} / 5</strong><span>宣传 0 / 1 / 25 / 50 / 75 / 100% 逐步缩小误差</span></div><p class="quality-note">宣传和买量都不影响发售资格。买量需要安排伙伴，并设置本周预算；未安排人手不扣投放费，¥0 暂停。</p><label class="field"><span>本周买量预算</span><select id="ad-budget" aria-label="本周买量预算"${disabled(active)}>${G.AD_BUDGETS.map(n=>`<option value="${n}"${s.adBudget===n?' selected':''}>${n===0?'暂停买量 · ¥0':yen(n)+' / 周'}</option>`).join('')}</select></label><div class="ad-ledger"><div><span>累计买量投入</span><b>${yen(a.spend)}</b></div><div><span>当前认知下净回款区间</span><b>${yen(a.low)}—${yen(a.high)}</b></div><div><span>预算转化比例（已扣分成）</span><b>${Math.round(a.lowRate*100)}%—${Math.round(a.highRate*100)}%</b></div></div><p class="quality-note">回款在发售时结算，按当时的综合真实评级：内容 40% / 完善度 30% / 商业化 20% / 推广 10%。C、D 档回款低于投入，B 档起有回本机会；发行分成会降低回款。评级未知时，区间很宽。</p></div>`;}
  function eventPanel(s){const pending=G.event(s);const last=s.logs.find(x=>x.text.includes('：')&&!x.text.startsWith('完成第')&&!x.text.startsWith('采用技术')&&!x.text.startsWith('扩展功能'));
    return `<section class="panel event-empty"><div class="event-eyebrow"><span>✧ ${pending?'本周事件 · 等待决定':'开发中的小插曲'}</span><span>${pending?'待处理':'每周 1 次'}</span></div><h3>${pending?pending.title:s.week===1?'故事，从第一周开始。':'每一步，都有新的可能。'}</h3><p>${pending?pending.text:s.week===1?'安排好伙伴的岗位。推进一周后，会发生属于这个项目的随机事件。':'灵感、意外、合作与团队日常，都会影响这款作品的诞生。事件与开发状态有关。'}</p>${pending?'<button class="btn-teal btn-small" style="margin-top:16px" data-action="prompt">处理这个事件 →</button>':last?`<div class="event-last">最近记录 · ${esc(last.text)}</div>`:''}</section>`;
  }
  function features(){const s=run,active=!busy();return `<p class="legend">功能增加内容评级基础和工作需求，追加工作也按项目规模放大。越晚加入，返工越多；每项功能持续增加 ¥22/周维护。冻结范围后不能增删。</p><section class="panel">${G.FEATURES.map(f=>{const owned=s.features.includes(f.id),p=G.featurePreview(s,f.id),req=owned?s.featureWork[f.id]:p.req;return `<div class="feature-row"><div><h3>${owned?'✓ ':''}${f.name} <span class="pill dim">扩展功能</span></h3><p>${f.desc} · 内容评级基础 +${((f.play+f.visual)*.13).toFixed(1)}</p><small>${Object.entries(req).map(([k,v])=>G.JOBS.find(j=>j.id===k).short+(owned?' · 范围占比 '+Math.round(v/s.req[k]*100)+'%':'完成度 '+(G.progress(s,k)*100).toFixed(1)+'% → '+(s.work[k]/(s.req[k]+v)*100).toFixed(1)+'%')).join(' · ')}<br>技术债 +${p.debt} · 维护 +22/周${!owned?' · 当前返工 +'+p.rework+'%':''}</small></div><button class="${owned?'btn-ghost':'btn-teal'}" data-action="${owned?'cut':'feature'}" data-id="${f.id}"${disabled(active&&!s.managed&&!s.designLocked&&(owned||s.money>=f.cost))}>${owned?'删减功能':'+ 加入 '+yen(f.cost)}</button></div>`;}).join('')}</section>`;}

  function logs(){return `<section class="panel"><div class="panel-head"><h2>开发记录</h2><small>记录认知与实际行动</small></div><div class="panel-body"><div class="dev-logs">${run.logs.map(l=>`<p><span>W${l.week}</span> ${esc(l.text)}</p>`).join('')}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>每周账本</h2></div><div class="ledger-wrap"><table class="ledger"><thead><tr><th>周次</th><th>总支出</th><th>其中买量</th><th>剩余资金</th><th>伙伴分工</th></tr></thead><tbody>${run.history.slice().reverse().map(h=>`<tr><td>${h.week}</td><td>${yen(h.cost)}</td><td>${yen(h.ads)}</td><td>${yen(h.money)}</td><td>${h.team.filter(m=>m.output>0).map(m=>esc(m.name)+' · '+G.JOBS.find(j=>j.id===m.job).name).join(' / ')}</td></tr>`).join('')||'<tr><td colspan="5">推进第一周后记录收支。</td></tr>'}</tbody></table></div></section>`;}


  function careerStats(){return `<div class="career-summary"><div class="stat"><span class="label">生涯资金</span><div class="value gold">${yen(meta.wallet)}</div><span class="note">开发扣款，收入到账，结余跨关继承</span></div><div class="stat"><span class="label">${meta.activeRunId?'当前关卡':'下一关'}</span><div class="value teal">${meta.stage}<small>关</small></div><span class="note">${meta.partners.length+2} 位全局团队成员</span></div><div class="stat"><span class="label">可用训练经验</span><div class="value">${meta.exp}<small>EXP</small></div><span class="note">训练能力后永久保留</span></div></div>`;}
  function career(){const released=meta.history.filter(h=>h.released),active=!!meta.activeRunId,team=[{...G.HERO,name:meta.hero.name,skills:meta.hero.skills},G.COMPANION,...meta.partners.map(id=>G.RECRUITS.find(r=>r.id===id))],candidates=G.RECRUITS.filter(r=>meta.knownPartners.includes(r.id)&&!meta.partners.includes(r.id));return title('YOUR STUDIO CAREER','人、能力与资金，一起走到下一关。','项目的完成度重新开始，生涯的积累持续保留。')+careerStats()+`
    <section class="panel"><div class="panel-head"><h2>主角成长 · ${esc(meta.hero.name)}</h2><span class="pill">${active?'项目开发中，结算后可训练':'关卡之间可训练'}</span></div><div class="panel-body"><form id="profile-form" class="profile-form"><label class="field"><span>主角称呼</span><input name="heroName" maxlength="12" required value="${esc(meta.hero.name)}"${disabled(!active)}></label><button class="btn-small"${disabled(!active)}>保存称呼</button></form><p class="quality-note">基础能力均为 100%。每次训练 +5，最高 200%；消耗经验，资金不变。训练后的能力带入后续每一个项目。</p><div class="growth-list">${G.SKILLS.map(j=>{const n=meta.hero.skills[j.id],price=G.trainingCost(meta,j.id);return `<div class="growth-row"><strong>${j.name}</strong><div class="ability-bar" style="--ability-color:${j.color}"><i style="width:${n/2}%"></i></div><b>${n}%</b><button class="btn-small" data-action="train" data-skill="${j.id}"${disabled(!active&&n<200&&meta.exp>=price)}>${n>=200?'已达上限':'+5 · '+price+' EXP'}</button></div>`;}).join('')}</div></div></section>
    <div class="section-heading"><h2>全局团队 · ${team.length} / 8</h2><small>伙伴加入后跨关留队，工资按当前团队计算</small></div><div class="global-team">${team.map(m=>`<article class="panel global-person">${P.portrait(m)}<div><h3>${esc(m.name)}</h3><p>${m.id==='hero'?'主角 · 能力永久成长':m.id==='ace'?'全能搭档':esc(m.title)}</p><small>基础周薪 ${yen(m.salary)}</small></div>${m.id!=='hero'&&m.id!=='ace'?`<button class="btn-small" data-action="career-dismiss" data-id="${m.id}"${disabled(!active&&meta.wallet>=100)}>暂别 · ¥100</button>`:'<span class="pill dim">固定成员</span>'}</article>`).join('')}</div>
    <div class="section-heading"><h2>已结识 · 待邀请 ${candidates.length} 人</h2><small>项目里程碑结识的伙伴会全局保留</small></div>${candidates.length?`<div class="global-team">${candidates.map(m=>`<article class="panel global-person">${P.portrait(m)}<div><h3>${esc(m.name)}</h3><p>${esc(m.title)} · ${P.summary(m)}</p><small>基础周薪 ${yen(m.salary)}</small></div><button class="btn-small" data-action="career-hire" data-id="${m.id}"${disabled(!active&&team.length<8&&meta.wallet>=180)}>邀请 · ¥180</button></article>`).join('')}</div>`:'<p class="legend">继续开发作品，完成原型、垂直切片与完整内容，结识更多伙伴。</p>'}
    <div class="section-heading"><h2>作品履历 · 已发售 ${released.length} 款</h2><small>累计获得 ${meta.earnedExp} EXP</small></div>${meta.history.length?meta.history.map(h=>`<article class="career-record"><div><h3>第 ${h.stage} 关 · ${esc(h.name)} <span class="pill dim">${h.released?'已发售':'已终止'}</span></h3><p>${G.SCALES.find(g=>g.id===h.scale).name} · 开发 ${h.weeks} 周 · 成本 ${yen(h.cost)} · 结束资金 ${yen(h.walletEnd)}</p><p>制作团队：${h.team.map(m=>esc(m.name)).join('、')}</p></div><div class="record-score">${h.released?h.rating:'—'}<small>制作经验 +${h.exp}</small></div></article>`).join(''):'<section class="panel people-empty"><p>第一款作品还在路上。发售或终止项目后，结余资金和整个团队会留下。</p></section>'}
    <p class="quality-note" style="margin-top:24px">资金不足时可以主动重新开始生涯，重置资金、能力、伙伴和履历。</p><button class="btn-ghost btn-small" data-action="reset-career"${disabled(!active)}>重新开始生涯</button>`;}

  function render(){hideMetricHelp();G.syncCareer(meta,run);const labels={home:'工作室大厅',game:'开发现场',career:'局外生涯'};document.querySelectorAll('.sidebar nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('location').textContent=labels[view];$('run-dot').style.display=run&&!run.over?'':'none';$('meta-mini').innerHTML='<div class="side-growth"><small>生涯资金</small><div style="margin-top:8px"><strong class="gold">'+yen(meta.wallet)+'</strong></div><p>可用经验 '+meta.exp+' EXP<br>全局团队 '+(meta.partners.length+2)+' 人 · 下一关 '+meta.stage+'</p></div>';
    $('app').innerHTML=({home,game,career}[view])();renderFooter();save();if(view==='game'&&!hiddenPrompt&&run&&!run.over&&run.pendingEvent)showEvent();}
  function renderFooter(){if(view!=='game'||!run||run.over){$('footer').innerHTML='';return;}const s=run,c=G.cost(s),pending=s.pendingEvent;$('footer').innerHTML=`<footer class="actionbar"><div><p><strong>第 ${s.week} 周 · 团队开发</strong><span class="break-mobile">　${s.reserve?s.reserve+' 人尚未分配岗位':'岗位调整不消耗时间'}</span></p><p class="${s.money<c.total?'danger-text':''}" style="margin-top:4px">${pending?'完成当前选择后才能继续开发':s.money<c.total?'预算不足，请处理资金或结束项目':'推进后支付 '+yen(c.total)+'，并触发一次随机事件'}</p></div><div class="action-controls"><div class="pace" aria-label="开发节奏">${[['rest','休整'],['normal','正常'],['crunch','赶工']].map(([id,n])=>`<button data-action="pace" data-pace="${id}" title="${id==='rest'?'效率 70%，士气 +12':id==='crunch'?'效率 135%，士气 −10，增加问题与技术债':'标准效率，士气 +1'}" class="${s.pace===id?'selected':''}"${disabled(!busy())}>${n}</button>`).join('')}</div><button data-action="${pending?'prompt':'advance'}" class="btn-primary next-week"${disabled(pending||s.money>=c.total)}>${pending?'完成当前选择':'推进一周'}　→</button></div></footer>`;}
  const metricPopup=document.createElement('aside');metricPopup.id='metric-help';metricPopup.className='metric-help';metricPopup.hidden=true;
  metricPopup.setAttribute('role','dialog');metricPopup.setAttribute('aria-modal','false');metricPopup.setAttribute('aria-labelledby','metric-help-title');document.body.append(metricPopup);
  let metricTrigger=null,metricPinned=false,metricHideTimer,suppressMetricFocus=false;
  document.addEventListener('pointerover',e=>{const b=e.target.closest('[data-metric-help]');if(b&&e.pointerType!=='touch'&&!metricPinned)showMetricHelp(b);});
  document.addEventListener('pointerout',e=>{const b=e.target.closest('[data-metric-help]');if(b&&!b.contains(e.relatedTarget)&&!metricPopup.contains(e.relatedTarget)&&!metricPinned)scheduleMetricHide();});
  metricPopup.addEventListener('pointerenter',()=>clearTimeout(metricHideTimer));
  metricPopup.addEventListener('pointerleave',e=>{if(!metricPinned&&!metricTrigger?.contains(e.relatedTarget))scheduleMetricHide();});
  document.addEventListener('focusin',e=>{const b=e.target.closest('[data-metric-help]');if(b){if(!suppressMetricFocus&&metricTrigger!==b)showMetricHelp(b);}else if(metricTrigger&&!metricPopup.contains(e.target))hideMetricHelp();});
  document.addEventListener('click',e=>{
    const b=e.target.closest('[data-metric-help]');
    if(b){e.preventDefault();if(metricTrigger===b&&metricPinned)hideMetricHelp();else showMetricHelp(b,true);return;}
    if(e.target.closest('.metric-help-close')){hideMetricHelp(true);return;}
    if(metricTrigger&&!metricPopup.contains(e.target))hideMetricHelp();
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!metricPopup.hidden){e.preventDefault();hideMetricHelp(true);}});
  window.addEventListener('resize',()=>hideMetricHelp());
  window.addEventListener('scroll',positionMetricHelp,true);

  const dialog=$('dialog');let dialogKind='';
  function showDialog(html,kind){hideMetricHelp();dialogKind=kind;dialog.innerHTML=`<div class="dialog-body">${html}</div>`;if(!dialog.open)dialog.showModal();}
  function close(){dialog.close();dialogKind='';}
  function dialogHeader(eye,name,closable=true){return `<div class="dialog-header"><div><div class="eyebrow">${eye}</div><h2 id="dialog-title">${name}</h2></div>${closable?'<button class="close-btn" data-action="close" aria-label="关闭窗口">×</button>':''}</div>`;}
  function setup(scaleId){if(run&&!run.over){showDialog(dialogHeader('ONE PROJECT AT A TIME','先完成当前项目。')+'<p class="dialog-desc">资金和整个团队共用一份生涯记录。请先发售或终止当前项目，再进入下一关。</p><div class="dialog-actions"><button data-action="close" class="btn-primary">继续当前项目</button></div>','setup-blocked');return;}setupScale=scaleId||setupScale;const g=G.SCALES.find(g=>g.id===setupScale),plan=G.scalePlan(g.id),affordable=meta.wallet>=plan.minFunds;showDialog(dialogHeader('LEVEL '+meta.stage,'开始第 '+meta.stage+' 关。')+`
    <p class="dialog-desc">继承生涯资金 <strong>${yen(meta.wallet)}</strong>、${esc(meta.hero.name)}的五项能力，以及 ${meta.partners.length+2} 人的全局团队。每一关都使用当前余额，不再补发启动资金。</p><form id="setup-form"><div class="setup-scales">${G.SCALES.map(x=>`<button type="button" class="${x.id===setupScale?'selected':''}" data-action="setup-scale" data-scale="${x.id}">${x.icon} ${x.name}<small>${G.scalePlan(x.id).personWeeks.toLocaleString("zh-CN")} 人周 · ${meta.wallet<G.scalePlan(x.id).minFunds?'资金不足':'可立项'}</small></button>`).join('')}</div><div class="scale-explainer"><strong>${g.name} · 需要 ${plan.personWeeks.toLocaleString("zh-CN")} 人周工作量</strong><p>以 100% 能力计算，每人每周基础产出 ${G.STANDARD_WEEKLY_WORK} 点，即 1 标准人周。同能力、同状态的人员每周产出相同；实际开发还受士气、磨合、协作与模式影响。</p><div class="setup-funds ${affordable?'':'insufficient'}"><b>立项需要 ${yen(plan.minFunds)} · 当前 ${yen(meta.wallet)}</b><span>${affordable?'资金充足，可以开始开发':'资金不足，还差 '+yen(plan.minFunds-meta.wallet)}</span><small>每标准人周按 ${yen(G.STANDARD_PERSON_WEEK_COST)} 校验启动资金，仅为立项门槛，不预扣款；实际支出仍按周结算。</small></div><small>规模影响全部 13 项工作和功能扩展的需求；各规模共用评级与收益规则。${g.multiplier>1?' 建议先积累资金与团队，再挑战较大规模。':' 适合从这里开始积累生涯。'}</small></div><label class="field"><span>作品名称</span><input name="name" maxlength="18" required value="${esc(g.title)}" autocomplete="off"></label><label class="field"><span>这款作品的目标 · 达成额外 +40 EXP</span><select name="objective"><option value="profit">商业回报：项目结余至少 ¥1,200</option><option value="acclaim">口碑佳作：综合真实评级至少 A-</option></select></label><div class="radio-line"><label><input type="radio" name="difficulty" value="normal" checked> 理想模式 · 稳定推进</label><label><input type="radio" name="difficulty" value="hard"> 真实模式 · 感受一下现实吧</label></div><details style="margin-top:17px;font-size:10px;color:var(--muted)"><summary>固定种子（可选，用于重玩同一组随机选择）</summary><label class="field" style="margin-top:10px"><input name="seed" type="number" min="1" max="4294967295" placeholder="留空则随机生成"></label></details><div id="setup-error" class="warning-note" role="alert"></div><div class="dialog-actions"><button type="button" class="btn-ghost" data-action="close">再想想</button><button class="btn-primary" type="submit"${disabled(affordable)}>${affordable?'开始本次开发 →':'资金不足，无法立项'}</button></div></form>`,'setup');}


  function showEvent(){const e=G.event(run);hiddenPrompt=false;showDialog(dialogHeader('WEEK '+String(run.week-1).padStart(2,'0')+' · '+e.tag,e.title)+`<div class="event-image" aria-hidden="true">${{inspiration:'✦',palette:'◈',coffee:'☕',backup:'▣',forms:'▤',feedback:'✉',bug:'⌘',showcase:'✧',scope:'◇',tired:'☾',break:'♧',discount:'◉',compat:'⌘',debt:'⌘'}[e.id]||'✦'}</div>${P.voice(run,e)}<p class="dialog-desc">${e.text}</p><div class="event-options">${e.choices.map((c,i)=>`<button class="event-option" data-action="event" data-index="${i}"${disabled(G.eventChoiceStatus(run,i).ok)}><div><strong>${c.label}</strong><small>${c.hint}${!G.eventChoiceStatus(run,i).ok?' · '+G.eventChoiceStatus(run,i).reason:''}</small></div><span>↗</span></button>`).join('')}</div><p class="quality-note">你的决定会自动保存。同一开发周只发生一次事件。</p>`,'event');}
  function result(){const r=run.result;showDialog(dialogHeader('THE TRUTH BEHIND THE QUESTION MARKS',r.released?'「'+esc(r.name)+'」发售了。':'把经验，留给下一作。')+`<div class="result-grade">${r.released?r.rating:'—'}<small>${r.released?'综合真实评级':'项目已终止'}</small></div>${r.ratings?`<div class="result-ratings">${G.GROUPS.filter(g=>g.id!=='release').map(g=>`<div><small>${g.rating}</small><strong>${r.ratings[g.id].grade}</strong></div>`).join('')}</div>`:''}<div class="result-grid"><div><label>项目规模</label><strong>${G.SCALES.find(g=>g.id===r.scale).name}</strong></div><div><label>开发时间</label><strong>${r.weeks} 周</strong></div><div><label>累计投入（含买量）</label><strong>${yen(r.cost)}</strong></div><div><label>自然收入</label><strong>${yen(r.organicRevenue)}</strong></div><div><label>买量净回款</label><strong>${yen(r.adRevenue)}</strong></div><div><label>买量投入 / 回款比例</label><strong>${yen(r.adSpend)} / ${r.released?(r.adRate*100).toFixed(1)+'%':'未发售'}</strong></div><div><label>项目结余（含融资）</label><strong class="${r.profit>=0?'teal':'red'}">${yen(r.profit)}</strong></div><div><label>本次制作经验</label><strong>+${r.exp} EXP</strong></div><div><label>结余资金 · 带入下一关</label><strong>${yen(r.walletEnd)}</strong></div></div><p class="result-note">共同完成：${r.team.map(m=>esc(m.name)).join('、')}<br>${r.objectiveOK?'✓ 制作人目标达成，额外 +40 EXP。':'本作未达成制作人目标，保留已获得的制作经验。'}<br>主角能力、全体伙伴和结余资金会带入下一关。</p><div class="dialog-actions"><button data-action="career" class="btn-ghost">查看作品履历</button><button data-action="setup" class="btn-primary">下一关 →</button></div>`,'result');}
  function release(){if(!G.canRelease(run))return;const f=G.forecast(run);showDialog(dialogHeader('READY TO SHIP','让玩家，给出最后的答案。')+`<p class="dialog-desc">资料准备和审核都已达到 100%，可以正式发售。其他工作无最低门槛，未完成部分会影响真实品质与收益。</p><div class="result-grid"><div><label>综合评级认知</label><strong>${esc(f.rating.text)}</strong></div><div><label>当前认知收入区间</label><strong>${yen(f.low)}—${yen(f.high)}</strong></div><div><label>其中买量回款区间</label><strong>${yen(f.ad.low)}—${yen(f.ad.high)}</strong></div><div><label>累计投入</label><strong>${yen(run.spent)}</strong></div></div><p class="quality-note">发售会揭晓四项真实评级和买量回款。宣传不足时，当前判断可能与实际差别很大。自然收入仍有 ±15% 市场波动；买量按发售时真实评级和投入金额结算。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">继续开发</button><button data-action="confirm-release" class="btn-primary">正式发售 ↗</button></div>`,'release');}
  function help(){showDialog(dialogHeader('STRATEGY HANDBOOK','投入多少，知道多少，何时发售。')+`<div class="manual"><p><strong>四档规模：</strong>微型、小型、中型、大型分别需要 54.4、163.2、489.6、1468.8 标准人周工作量。100% 能力每周基础产出 10 点为 1 人周，立项需持有每标准人周 ¥100 的资金，不预扣款。相同人员与状态，每周产出相同；完成度 = 已完成工作 ÷ 总需求。因此同一周工作，在小项目推进更多完成度。规模影响全部 13 项工作和功能扩展；上架仍没有软上限，但也需要完成该规模的全部上架工作。各规模共用评级与收益规则，请用资金和团队支持更长的开发。</p><p><strong>五类十三项：</strong>游戏内容（题材、玩法、子主题）；程序构架（开发进度、系统协作、测试）；商业化（广告变现、用户付费、IP衍生）；宣发推广（宣传、买量）；上架（资料准备、审核进度）。在人物卡为每人安排一项工作，专业能力决定产出。</p><p><strong>工作与评级不同：</strong>完成度代表当前成果，评级是目前完成度加上本项目固定的大范围随机值。同一完成度也可能是 B 或 S；继续完善可以提高基础值，刷新和反复查看不重掷。</p><p><strong>两种上限：</strong>除上架外，11 项完成度初始软上限 70%。事件仅解锁更高上限，不直接增减完成度；上限按项保存，每次一般提高 15 个百分点，最高为刚性上限 100%。提高上限后还需安排工作，才会提高评级基础。横线标记当前软上限。</p><p><strong>理想与真实：</strong>理想模式工作稳定推进。真实模式以周初完成度判定：低于 30% 正常；30% 至不足 50% 效率 65%；50% 至 70% 效率 35%，正向推进的 20% 会随机扣除另一项非上架工作的完成度；超过 70% 增减各 50%，幅度为基础产能的 20%—100%，预览不透露本次结果。上架始终正常推进，也不会被其他工作牵连。两种模式都使用生涯余额，工资规则相同。</p><p><strong>先获得认知：</strong>四类评级初始为 ?????，宣传进度越高，问号越少。B???? 是粗略判断，可能偏离很远；宣传 100% 揭示当前真实评级。作品继续开发时，评级也会变化，认知范围随之更新。上架状态始终明确。</p><p><strong>宣发是选择：</strong>宣传用于了解作品；买量用于投入资金换取未来回款。安排买量岗位并选择预算后，每周扣费，未安排人手或预算 ¥0 不扣费。买量进度满后，继续安排仍会追加投放；发售前没有回款。</p><p><strong>投放与风险：</strong>综合真实评级按内容 40%、完善度 30%、商业化 20%、推广 10% 计算。净回款比例：D 档 15—40%，C 档 55—90%，B 档 105—140%，A 档 165—230%，S 档 270—380%；若签发行合作，再扣 22% 分成。C、D 档一定亏损，B 档起有回本机会。</p><p><strong>上架是硬条件：</strong>资料准备 100% 后才可推进审核；审核也到 100% 即可发售。其他工作不强制满进度，但提前发售可能得到低评级和亏损。</p><p><strong>局外成长：</strong>主角五项初始能力均为 100%，关卡之间可用经验训练，每次 +5、最高 200%。开发直接扣生涯资金，发售收入到账后继承到下一关，不重新发启动金。伙伴与结识名单也跨关保留。项目完成度、软上限、问题和士气在新项目重新开始。</p><p><strong>人物与成本：</strong>主角加阿策两人开局，伙伴随核心进度结识，并在加入后跨关留队。转到另一具体工作会磨合一周，即使同属一类；同岗第一人全额，其他人按 45% 协作产能计算。待命照付周薪。</p><p><strong>依赖与构筑：</strong>内容支持开发，开发支持系统协作和测试。系统协作持续偿债，测试持续修问题。内容 60% 可冻结范围，提高实现效率，放弃扩功能；解冻花 ¥180 并返工。功能会改变品质潜力和持续成本。</p><p><strong>每一周：</strong>支付工资、维护、工具和买量费用，推进安排，再触发一次事件。无固定周数上限。发售或终止结算经验，项目和生涯共同保存，能力、资金与全局伙伴跨关继承。</p></div><div class="dialog-actions"><button data-action="close" class="btn-primary">回到工作室</button></div>`,'help');}

  function finish(released){const r=G.finish(run,released);if(!r){toast('请先完成当前选择，或检查发售准备。');return;}meta=G.settle(meta,run);close();save();render();result();}
  document.addEventListener('change',e=>{const el=e.target;if(el.id==='ad-budget'&&run){G.setAdBudget(run,Number(el.value));render();return;}if(!el.matches('select[data-member]')||!run)return;const ok=G.assignMember(run,el.dataset.member,el.value);if(!ok)toast('这个岗位暂时不能分配。');render();});
  document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();const name=new FormData(e.target).get('heroName');if(!G.renameHero(meta,name))toast('请在项目结算后修改称呼。');render();return;}if(e.target.id!=='setup-form')return;e.preventDefault();const fd=new FormData(e.target);try{run=G.newRun({scale:setupScale,name:fd.get('name'),hard:fd.get('difficulty')==='hard',seed:fd.get('seed'),objective:fd.get('objective')},meta);}catch(err){$('setup-error').textContent=err.message;return;}view='game';tab='work';hiddenPrompt=false;close();render();window.scrollTo(0,0);});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action;
    if(a==='close'){hiddenPrompt=true;close();return;}
    if(a==='audio'){const st=audio.getState();audio.setSettings({muted:!(st.settings?.muted??st.muted)});audio.unlock();return;}
    if(a==='help'){help();return;}
    if(a==='setup'){setup(b.dataset.scale);return;}
    if(a==='setup-scale'){const form=$('setup-form'),name=form.elements.name.value,mode=form.elements.difficulty.value,objective=form.elements.objective.value,seed=form.elements.seed.value,old=G.SCALES.find(g=>g.id===setupScale).title;setup(b.dataset.scale);if(name&&name!==old)$('setup-form').elements.name.value=name;$('setup-form').elements.difficulty.value=mode;$('setup-form').elements.objective.value=objective;$('setup-form').elements.seed.value=seed;return;}
    if(['home','nav','continue','career'].includes(a)){view=a==='nav'?b.dataset.view:a==='continue'?'game':a==='career'?'career':'home';close();hiddenPrompt=false;render();window.scrollTo(0,0);return;}
    if(a==='result'){result();return;}
    if(a==='tab'){tab=b.dataset.tab;render();return;}
    if(a==='train'){if(!G.train(meta,b.dataset.skill))toast('当前无法训练，请检查经验或先结算项目。');render();return;}
    if(a==='career-hire'){if(!G.hirePartner(meta,b.dataset.id))toast('当前无法邀请，请检查资金或先结算项目。');render();return;}
    if(a==='career-dismiss'){const member=G.RECRUITS.find(r=>r.id===b.dataset.id);if(!member||meta.activeRunId)return;showDialog(dialogHeader('TEAM CHANGE','与'+esc(member.name)+'暂别？')+'<p class="dialog-desc">支付 ¥100，之后不再计算这位伙伴的工资。结识关系保留，后续可再次邀请。</p><div class="dialog-actions"><button data-action="close">继续同行</button><button data-action="confirm-career-dismiss" data-id="'+member.id+'">确认暂别 · ¥100</button></div>','career-dismiss');return;}
    if(a==='confirm-career-dismiss'){G.dismissPartner(meta,b.dataset.id);close();render();return;}
    if(a==='reset-career'){if(meta.activeRunId)return;showDialog(dialogHeader('A FRESH CAREER','重新开始整个生涯？')+'<p class="dialog-desc">资金恢复到 ¥7,600，主角五项能力恢复为 100%。伙伴、结识名单、经验和作品履历都会清空。</p><div class="dialog-actions"><button data-action="close">保留当前生涯</button><button data-action="confirm-reset-career">确认重新开始</button></div>','reset-career');return;}
    if(a==='confirm-reset-career'){if(meta.activeRunId)return;meta=G.emptyMeta();run=null;close();view='career';render();return;}
    if(!run||run.over)return;
    if(a==='prompt'){if(run.pendingEvent)showEvent();return;}
    if(a==='event'){if(G.resolveEvent(run,Number(b.dataset.index))){close();hiddenPrompt=false;render();}return;}
    if(a==='release'){release();return;}
    if(a==='dismiss'){const m=run.team.find(m=>m.id===b.dataset.id);if(!m||m.kind!=='partner'||busy())return;showDialog(dialogHeader('UNTIL NEXT TIME','与'+esc(m.name)+'暂别？')+`<p class="dialog-desc">支付 ¥100 安置费，之后不再计入${esc(m.name)}的周薪。本项目内不能再次邀请；结识关系会保留到后续关卡。此操作占用本周管理行动。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">继续同行</button><button data-action="downsize" data-id="${m.id}">确认暂别 · ¥100</button></div>`,'dismiss');return;}
    if(a==='confirm-release'){finish(true);return;}
    if(a==='confirm-abort'){finish(false);return;}
    if(a==='abort'){showDialog(dialogHeader('PAUSE THIS PROJECT','结束这个项目？')+`<p class="dialog-desc">当前作品不会发售。已完成的 ${run.milestones.length} 个里程碑可保留 ${Math.min(30,run.milestones.length*8)} 点经验，已经花掉的资金不返还；剩余资金、主角能力和已加入的伙伴会带入下一关。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">继续开发</button><button data-action="confirm-abort">结束并结算</button></div>`,'abort');return;}
    if(busy()){toast('请先完成当前随机事件选择。');return;}
    let ok=true;

    if(a==='budget')ok=G.setAdBudget(run,Number(b.dataset.value));

    if(a==='freeze')ok=G.freeze(run);
    if(a==='pace'){run.pace=b.dataset.pace;}
    if(a==='assign')ok=G.assign(run,b.dataset.job,Number(b.dataset.delta));
    if(a==='hire')ok=G.hire(run,b.dataset.id);
    if(a==='downsize'){ok=G.downsize(run,b.dataset.id);close();}
    if(a==='feature')ok=G.feature(run,b.dataset.id);
    if(a==='cut')ok=G.cutFeature(run,b.dataset.id);
    if(a==='funding'){showDialog(dialogHeader('PUBLISHING PARTNERSHIP','给开发，多一点余地。')+`<p class="dialog-desc">发行商愿意预付 ¥2,200，换取本作发售收入的 22%。这笔资金不增加品质，也不降低完成度推进所需投入，每个项目只能签一次。</p><p class="quality-note">发售收入预估将自动按扣除分成后的数值显示。</p><div class="dialog-actions"><button data-action="close" class="btn-ghost">先不合作</button><button class="btn-primary" data-action="confirm-funding">接受合作，获得 ¥2,200</button></div>`,'funding');return;}
    if(a==='confirm-funding'){ok=G.funding(run);close();}
    if(a==='advance'){const r=G.advance(run);ok=r.ok;if(!ok)toast(r.reason);hiddenPrompt=false;}
    if(!ok&&a!=='advance')toast('当前条件不满足，操作未执行。');render();
  });
  dialog.addEventListener('cancel',()=>{hiddenPrompt=true;dialogKind='';});
  document.addEventListener('keydown',e=>{if(e.key===' '&&view==='game'&&!dialog.open&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();document.querySelector('.next-week')?.click();}});
  // Terminating a project is always visible from its history tab, including an exhausted budget.
  const originalLogs=logs;logs=function(){return originalLogs()+(!run.over?'<div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn-ghost btn-small" data-action="abort">终止当前项目并结算</button></div>':'');};
  if(run&&run.over){meta=G.settle(meta,run);}render();
})();
